<template><div class="k8s-browser"><aside class="k8s-tree"><header><strong>K8s 集群</strong><span>{{inventory?.clusters?.length||0}}</span></header><button v-for="cluster in inventory?.clusters||[]" :key="cluster.id" :class="{active:selectedCluster?.id===cluster.id}" @click="selectCluster(cluster)"><Boxes/><div><strong>{{cluster.name}}</strong><span>{{cluster.namespaceCount}} 个命名空间 · {{cluster.version||'-'}}</span></div></button><label class="cluster-toggle"><input v-model="includeClusterResources" type="checkbox">显示集群级资源</label></aside><main class="k8s-content"><header><div><span>KUBERNETES ASSET EXPLORER</span><h2>{{selectedCluster?.name||'请选择集群'}}</h2><p>{{visibleResources.length}} 个资源 · 已选 {{selectedNamespaces.length}} 个命名空间</p></div><input v-model="query" placeholder="搜索资源名称 / 类型 / 状态"></header><div ref="picker" class="namespace-picker"><div class="namespace-dropdown"><span>命名空间（可多选）</span><button class="namespace-trigger" @click.stop="namespaceOpen=!namespaceOpen"><b>{{selectionText}}</b><ChevronDown/></button><div v-if="namespaceOpen" class="namespace-menu" @click.stop><header><strong>选择命名空间</strong><div><button @click="selectAllNamespaces">全选</button><button @click="clearNamespaces">清空</button></div></header><label v-for="item in selectedCluster?.namespaces||[]" :key="item.id"><input type="checkbox" :checked="selectedNamespaces.includes(item.name)" @change="toggleNamespace(item.name)"><span>{{item.name}}</span><small>{{resourceTotal(item.counts)}} 个资源</small><Check v-if="selectedNamespaces.includes(item.name)"/></label><p v-if="!(selectedCluster?.namespaces||[]).length">暂无命名空间</p></div></div><div class="namespace-chips"><button v-for="name in selectedNamespaces" :key="name" @click="removeNamespace(name)">{{name}} ×</button><span v-if="!selectedNamespaces.length">未选择命名空间时仅显示集群级资源</span></div></div><div v-if="error" class="discovery-error">{{error}}</div><div v-if="selectedCluster" class="k8s-resource-groups"><section v-for="group in visibleGroups" :key="group.type"><header><component :is="group.icon"/><strong>{{group.label}}</strong><b>{{group.items.length}}</b></header><div class="k8s-resource-grid"><button v-for="asset in group.items" :key="asset.id" @click="emit('select',asset.id)"><div class="resource-top"><strong>{{asset.name}}</strong><b :data-status="asset.status">{{statusText(asset.status)}}</b></div><p>{{resourceMeta(asset)}}</p><small>{{assetNamespace(asset)||asset.location||'集群级资源'}}</small></button><p v-if="!group.items.length">暂无资源</p></div></section></div><div v-else class="empty-cluster"><Boxes/><strong>选择一个 K8s 集群</strong><span>通过命名空间多选查看 Pod、Service、Workload、存储和 Ingress</span></div></main></div></template>

<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,type Component } from 'vue'
import { Activity, Boxes, Check, ChevronDown, Database, GitFork, Layers, Network, Server, ShieldCheck } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/useAuthStore'
import type { Asset } from '@/features/cmdb/types'
type Namespace={id:string;name:string;status:string;counts:Record<string,number>;resources:Asset[]};type Cluster={id:string;name:string;status:string;version?:string;namespaceCount:number;counts:Record<string,number>;namespaces:Namespace[];clusterResources:Asset[]};type Inventory={clusters:Cluster[]}
const emit=defineEmits<{(event:'select',id:string):void}>();const auth=useAuthStore(),inventory=ref<Inventory>(),selectedCluster=ref<Cluster>(),selectedNamespaces=ref<string[]>([]),includeClusterResources=ref(false),namespaceOpen=ref(false),picker=ref<HTMLElement>(),query=ref(''),error=ref('')
const namespaceMap=computed(()=>Object.fromEntries((selectedCluster.value?.namespaces||[]).map(item=>[item.name,item])))
const visibleResources=computed(()=>{let source:Asset[]=[];for(const name of selectedNamespaces.value){source.push(...(namespaceMap.value[name]?.resources||[]))}if(includeClusterResources.value)source.push(...(selectedCluster.value?.clusterResources||[]));const q=query.value.trim().toLowerCase();return source.filter(a=>!q||(a.name+' '+a.type+' '+a.typeName+' '+a.status+' '+attr(a,'workload_kind')+' '+attr(a,'pod_phase')+' '+attr(a,'service_type')).toLowerCase().includes(q))})
const visibleGroups=computed(()=>{const defs=[{type:'workload',label:'工作负载',icon:Layers,types:['k8s-workload']},{type:'pod',label:'Pod',icon:Boxes,types:['k8s-pod']},{type:'service',label:'Service',icon:Network,types:['k8s-service']},{type:'storage',label:'存储',icon:Database,types:['k8s-pvc','k8s-pv','k8s-storageclass']},{type:'ingress',label:'Ingress',icon:GitFork,types:['k8s-ingress']},{type:'cluster',label:'集群级资源',icon:Server,types:['k8s-node']}];return defs.map(group=>({...group,items:visibleResources.value.filter(a=>group.types.includes(a.type))})).filter(group=>group.items.length>0)})
function attr(asset:Asset,name:string){return asset.attributes?.find(item=>item.name===name)?.value||''}
function resourceTotal(counts:Record<string,number>){return Object.values(counts||{}).reduce((a,b)=>a+b,0)}
function selectCluster(cluster:Cluster){selectedCluster.value=cluster;const preferred=cluster.namespaces.find(item=>item.name==='ops-qa')||cluster.namespaces[0];selectedNamespaces.value=preferred?[preferred.name]:[];includeClusterResources.value=false;namespaceOpen.value=false}
function removeNamespace(name:string){selectedNamespaces.value=selectedNamespaces.value.filter(item=>item!==name)}
function toggleNamespace(name:string){selectedNamespaces.value=selectedNamespaces.value.includes(name)?selectedNamespaces.value.filter(item=>item!==name):[...selectedNamespaces.value,name]}
function selectAllNamespaces(){selectedNamespaces.value=(selectedCluster.value?.namespaces||[]).map(item=>item.name)}
function clearNamespaces(){selectedNamespaces.value=[]}
function closePicker(event:MouseEvent){if(!picker.value?.contains(event.target as Node))namespaceOpen.value=false}
const selectionText=computed(()=>{if(!selectedNamespaces.value.length)return '请选择命名空间';if(selectedNamespaces.value.length<=2)return selectedNamespaces.value.join('、');return `已选择 ${selectedNamespaces.value.length} 个命名空间`})
function statusText(status:string){return ({online:'运行中',warning:'异常',offline:'离线'} as Record<string,string>)[status]||status}
function assetNamespace(asset:Asset){return attr(asset,'namespace')}
function resourceMeta(asset:Asset){if(asset.type==='k8s-workload'){const kind=attr(asset,'workload_kind')||'Workload';const ready=attr(asset,'ready_replicas')||'0';const total=attr(asset,'replicas')||'0';return `${kind} · 就绪 ${ready}/${total}`}if(asset.type==='k8s-pod'){return `${attr(asset,'pod_phase')||'Unknown'} · 重启 ${attr(asset,'restart_count')||'0'} 次`}if(asset.type==='k8s-service'){return `${attr(asset,'service_type')||'Service'} · ${attr(asset,'cluster_ip')||asset.ip||'-'}`}if(asset.type==='k8s-pvc'){return `${attr(asset,'volume_phase')||'-'} · ${attr(asset,'capacity')||attr(asset,'requested_storage')||'-'}`}if(asset.type==='k8s-pv'){return `${attr(asset,'volume_phase')||'-'} · ${attr(asset,'capacity')||'-'}`}if(asset.type==='k8s-storageclass'){return `${attr(asset,'provisioner')||'-'} · ${attr(asset,'reclaim_policy')||'-'}`}return `${asset.typeName} · ${asset.location||'-'}`}
async function load(){try{const response=await fetch('/api/v1/cmdb/kubernetes',{headers:{Authorization:`Bearer ${auth.token}`}});if(!response.ok)throw new Error(`请求失败 (${response.status})`);inventory.value=await response.json() as Inventory;if(inventory.value.clusters.length)selectCluster(inventory.value.clusters[0])}catch(reason){error.value=reason instanceof Error?reason.message:'K8s 资产加载失败'}}
onMounted(()=>{load();document.addEventListener('mousedown',closePicker)})
onBeforeUnmount(()=>document.removeEventListener('mousedown',closePicker))
</script>

<style scoped>
.k8s-browser{display:grid;grid-template-columns:280px minmax(0,1fr);min-height:680px;border:1px solid #24314d;border-radius:12px;overflow:hidden;background:#081522}.k8s-tree{padding:12px;border-right:1px solid #24314d;background:#0b1a29}.k8s-tree>header,.k8s-content>header{display:flex;align-items:center;justify-content:space-between;gap:12px}.k8s-tree>header{padding:8px 10px}.k8s-tree>header span{color:#6f91a5}.k8s-tree>button{width:100%;display:flex;align-items:center;gap:10px;margin-top:8px;padding:11px;text-align:left}.k8s-tree>button div{display:flex;flex-direction:column}.k8s-tree>button span{font-size:11px;color:#6f91a5}.k8s-tree>button.active{border-color:#16b8e4;background:#0c4967}.cluster-toggle{display:flex;align-items:center;gap:8px;margin:16px 10px 4px;color:#9fb5c7}.k8s-content{min-width:0;padding:20px}.k8s-content>header input{max-width:300px}.k8s-content>header span{color:#22d3ee;font-size:11px;letter-spacing:.14em}.k8s-content h2{margin:6px 0}.k8s-content p{margin:0;color:#6f91a5}.namespace-picker{display:grid;grid-template-columns:minmax(300px,420px) 1fr;gap:16px;align-items:start;margin:16px 0}.namespace-dropdown{position:relative;display:flex;flex-direction:column;gap:6px}.namespace-trigger{width:100%;display:flex;align-items:center;justify-content:space-between}.namespace-menu{position:absolute;top:68px;left:0;right:0;z-index:20;max-height:360px;overflow:auto;padding:8px;border:1px solid #1d556d;border-radius:10px;background:#091b29;box-shadow:0 18px 45px #000a}.namespace-menu>header{display:flex;justify-content:space-between;align-items:center;padding:7px 8px 10px;border-bottom:1px solid #173c59}.namespace-menu>header div{display:flex;gap:6px}.namespace-menu>label{display:grid;grid-template-columns:auto 1fr auto auto;align-items:center;gap:9px;padding:9px 8px;border-radius:6px;cursor:pointer}.namespace-menu>label:hover{background:#0c2a40}.namespace-menu input{width:auto}.namespace-menu small{color:#6f91a5}.namespace-menu svg{width:15px;color:#22d3ee}.namespace-menu p{padding:18px;text-align:center}.namespace-chips{display:flex;flex-wrap:wrap;gap:6px;padding-top:22px}.namespace-chips button{padding:5px 9px}.namespace-chips span{color:#6f91a5;font-size:12px}.k8s-resource-groups{display:grid;gap:14px}.k8s-resource-groups>section{border:1px solid #18384a;border-radius:10px;background:#091b29}.k8s-resource-groups>section>header{display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid #123043}.k8s-resource-groups>section>header svg{color:#22d3ee}.k8s-resource-groups>section>header b{margin-left:auto;color:#7890aa}.k8s-resource-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px;padding:12px}.k8s-resource-grid>button{display:block;text-align:left;min-width:0;padding:12px}.resource-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.resource-top b{font-size:11px;color:#2dd4bf}.resource-top b[data-status=warning]{color:#f59e0b}.resource-top b[data-status=offline]{color:#fb7185}.k8s-resource-grid p{font-size:12px;margin:7px 0}.k8s-resource-grid small{display:block;color:#6f91a5;font-size:11px}.k8s-resource-grid>p{grid-column:1/-1;color:#64748b;padding:8px}.empty-cluster{min-height:460px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#6f91a5}.empty-cluster svg{width:44px;height:44px;color:#22d3ee}.empty-cluster strong{color:#dcecff;margin-top:12px}@media(max-width:900px){.k8s-browser{grid-template-columns:1fr}.k8s-tree{border-right:0;border-bottom:1px solid #24314d}.namespace-picker{grid-template-columns:1fr}.k8s-content>header{flex-direction:column;align-items:flex-start}.k8s-content>header input{max-width:none;width:100%}}
</style>
